func (h hospitalServiceHandler) getRooms(ctx context.Context, _ connect.Spec, stream connect.ServerStream) error {
	var req v1.Empty
	if err := stream.Receive(&req); err != nil {
		return err
	}
	res, err := h.svc.GetRooms(ctx, &req)
	if err != nil {
		return err
	}
	return stream.Send(res)
}
